1	import { describe, expect, it, vi } from "vitest";
2	import { createServer } from "node:net";
3	import path from "node:path";
4	import { fileURLToPath } from "node:url";
5	import { runToCompletion } from "@relis/test-utils";
6	import { runMigrate } from "../../../packages/database/src/migrate.ts";
7	
8	// packages/database/src/migrate.ts is the migration entry point for the
9	// two prescribed database targets (control/project — see
10	// context/project-structure.md). Neither prisma/control/schema.prisma nor
11	// prisma/project/schema.prisma defines a model: no domain has been
12	// authorized. This file proves:
13	//  - Missing/invalid configuration prevents Prisma from ever being
14	//    invoked (dependency-injected `runPrisma`, ordering check).
15	//  - Valid configuration reaches the downstream Prisma invocation with
16	//    the validated connection string.
17	//  - A downstream (Prisma) failure is propagated as the exit code.
18	//  - Diagnostics never leak a secret/malformed connection string.
19	//  - A REAL Prisma CLI invocation (no injection) against a deliberately
20	//    unreachable database genuinely fails and propagates nonzero — never
21	//    touching a real database, but exercising real Prisma tooling.
22	//
23	// Real-Prisma-subprocess determinism history (both addressed below, but
24	// distinct — do not conflate them):
25	//  - Hypothesis (addressed, not the confirmed cause): a fixed low port
26	//    (originally "1") is not guaranteed free/refusing in every environment.
27	//    getUnusedLoopbackPort() replaces it with a dynamically-verified-free
28	//    port. This is still worth keeping (a real, if smaller, source of
29	//    nondeterminism) but did not, by itself, explain the originally
30	//    reported failure.
31	//  - Confirmed cause: an inherited RUST_LOG=warn in the environment running
32	//    this suite makes Prisma's schema-engine binary emit a generic,
33	//    detail-free "Schema engine error:" instead of the structured P1001
34	//    connection diagnostic, for the IDENTICAL command and connection
35	//    string — independently verified (RUST_LOG=warn: generic error;
36	//    RUST_LOG=info or unset: P1001). buildMigrationSubprocessEnv() strips
37	//    RUST_LOG from the real Prisma subprocess's own environment only; it
38	//    never touches this test process's own `process.env` or any machine
39	//    setting.
40	
41	const here = path.dirname(fileURLToPath(import.meta.url));
42	const repoRoot = path.resolve(here, "../../..");
43	const databaseDir = path.join(repoRoot, "packages", "database");
44	
45	const SECRET_SENTINEL = "s3cr3t-should-never-leak";
46	
47	/**
48	 * Returns a loopback port confirmed free at the moment of the call (briefly
49	 * bound, then released) instead of a fixed guess like the reserved-looking
50	 * port 1 this replaced. A fixed low port is not guaranteed unused, reachable
51	 * -but-refusing, or even unrestricted-to-connect-to in every environment —
52	 * it can be already bound, proxied, or subject to sandbox-specific network
53	 * policy that produces something other than a clean, fast connection
54	 * refusal. An OS-assigned ephemeral port that this process itself just
55	 * verified as free carries none of those assumptions.
56	 *
57	 * Kept as a real hardening in its own right, but note: this alone did NOT
58	 * resolve the originally reported "Schema engine error:" failure — see
59	 * buildMigrationSubprocessEnv below for the confirmed cause.
60	 */
61	function getUnusedLoopbackPort(): Promise<number> {
62	  return new Promise((resolve, reject) => {
63	    const server = createServer();
64	    server.on("error", reject);
65	    server.listen(0, "127.0.0.1", () => {
66	      const address = server.address();
67	      if (address === null || typeof address === "string") {
68	        server.close();
69	        reject(new Error("Failed to obtain an ephemeral loopback port"));
70	        return;
71	      }
72	      const { port } = address;
73	      server.close(() => resolve(port));
74	    });
75	  });
76	}
