1	#!/usr/bin/env node
2	import { execFile, spawn } from "node:child_process";
3	import { createRequire } from "node:module";
4	import path from "node:path";
5	import { fileURLToPath, pathToFileURL } from "node:url";
6	import {
7	  ConfigValidationError,
8	  checkPortConflicts,
9	  loadApiConfig,
10	  loadDatabaseConfigForTarget,
11	  loadWebRuntimeConfig,
12	  loadWorkerConfig,
13	  PortConflictError,
14	  resolveEffectiveEnv,
15	  validateConsistentRuntimeMode,
16	  validateRuntimeMode,
17	} from "@relis/config";
18	import { parsePublicWebConfig } from "@relis/config/public";
19	
20	/**
21	 * Minimal local deployment entry point: validates every selected
22	 * process's configuration up front, runs the control-database migration,
23	 * builds each app, runs apps/worker once (see below), then starts and
24	 * supervises apps/api and apps/web (production `start`) as long-running
25	 * child processes.
26	 *
27	 * apps/worker currently only logs its own startup and exits (no queue
28	 * consumer exists yet — see AGENTS.md/context/stack.yml: background-job
29	 * technology is still undecided, and this task does not decide it or turn
30	 * the worker into one). It is therefore run as a completing STEP here,
31	 * like build/migrate, not as a supervised long-running service: treating
32	 * its intentional, preserved exit as a supervised process's "unexpected
33	 * exit" would tear down an otherwise-successful deployment. When a real
34	 * queue consumer is implemented, apps/worker belongs in the supervised
35	 * service set below instead.
36	 *
37	 * This is plain Node child-process orchestration — no Docker, no CI/CD, no
38	 * new orchestration technology. Docker Compose remains the prescribed
39	 * local/dev/test runtime (context/stack.yml) but is a separate,
40	 * unauthorized-here scaffolding effort (see README "Deployment").
41	 *
42	 * Usage: node tooling/scripts/deploy.mjs [--skip-migrate] [--skip-build] [--skip-worker]
43	 */
44	
45	const here = path.dirname(fileURLToPath(import.meta.url));
46	const repoRoot = path.resolve(here, "..", "..");
47	const apiDir = path.join(repoRoot, "apps", "api");
48	const webDir = path.join(repoRoot, "apps", "web");
49	const workerDir = path.join(repoRoot, "apps", "worker");
50	const databaseDir = path.join(repoRoot, "packages", "database");
51	
52	function require_(specifier, fromDir) {
53	  const require = createRequire(pathToFileURL(path.join(fromDir, "package.json")));
54	  return require.resolve(specifier);
55	}
56	
57	function resolveTsxBin() {
58	  const tsxPackageJson = require_("tsx/package.json", databaseDir);
59	  return path.join(path.dirname(tsxPackageJson), "dist", "cli.mjs");
60	}
61	
62	/**
63	 * Resolves every selected process's effective configuration independently
64	 * from the SAME base environment snapshot (mirroring check-ports — see
65	 * packages/config/src/ports.ts): apps/api, apps/web, apps/worker, AND the
66	 * control database (packages/database), each via `resolveEffectiveEnv`
67	 * with the same root/package/tier precedence the standalone entry points
68	 * themselves use — not read directly from `baseEnv`/`process.env`, which
69	 * would silently ignore any `.env` file those entry points would
70	 * otherwise have honored.
71	 *
72	 * Validates each with its own existing schema (no duplicated rules), plus
73	 * apps/web's additional NODE_ENV-consistency rule (the same one
74	 * apps/web/scripts/run.mjs enforces on itself), and checks for a port
75	 * conflict between apps/api and apps/web. Nothing is spawned as part of
76	 * this function: a failure here — including a failure to even RESOLVE an
77	 * environment, not just to validate one — must prevent every subsequent
78	 * build/migrate/start step, and is always reported as a safe diagnostic,
79	 * never a raw exception or value.
80	 *
81	 * On success, every returned env has its NODE_ENV explicitly set to the
82	 * exact `mode` used here for tier selection. Each entry point re-runs its
83	 * own (lenient) env-file resolution when it starts; explicitly forcing
84	 * NODE_ENV to the already-decided mode means that re-resolution can only
85	 * ever confirm the same mode, never silently diverge to a different one.
86	 */
87	export function validateDeployment(baseEnv, options = {}) {
88	  let mode;
89	  let apiEnv;
90	  let webEnv;
91	  let workerEnv;
92	  let databaseEnv;
93	
94	  try {
95	    // Initial mode selection is INSIDE the safe boundary too: an
96	    // invalid/empty OS-provided NODE_ENV must produce the same structured,
97	    // value-free diagnostic as every other failure here, not escape as an
98	    // uncaught exception.
99	    mode = validateRuntimeMode(baseEnv.NODE_ENV, "production", "deploy");
100	    apiEnv = resolveEffectiveEnv(mode, apiDir, baseEnv);
101	    webEnv = resolveEffectiveEnv(mode, webDir, baseEnv);
102	    workerEnv = resolveEffectiveEnv(mode, workerDir, baseEnv);
103	    databaseEnv = resolveEffectiveEnv(mode, databaseDir, baseEnv);
104	
105	    loadApiConfig(apiEnv);
106	    loadWorkerConfig(workerEnv);
107	    loadWebRuntimeConfig(webEnv);
108	    parsePublicWebConfig({ NEXT_PUBLIC_API_URL: webEnv.NEXT_PUBLIC_API_URL });
109	    // The same rule apps/web/scripts/run.mjs enforces on itself: an
110	    // invalid/empty/conflicting file-provided NODE_ENV must be rejected
111	    // here too, before any deployment side effect — not only when
112	    // apps/web happens to be started directly.
113	    validateConsistentRuntimeMode(webEnv.NODE_ENV, mode);
114	    checkPortConflicts(apiEnv, webEnv);
115	    if (!options.skipMigrate) {
116	      // Only the control database is migrated automatically here: the
117	      // project schema is applied per-project (see README "Migration"),
118	      // not as a single global deploy step, and is out of scope.
119	      loadDatabaseConfigForTarget("control", databaseEnv);
120	    }
121	  } catch (error) {
122	    if (error instanceof ConfigValidationError || error instanceof PortConflictError) {
123	      return { ok: false, diagnostic: error.toDiagnostic(), mode, apiEnv, webEnv, workerEnv, databaseEnv };
124	    }
125	    // An unexpected failure (e.g. an I/O error resolving a .env file)
126	    // must still produce a safe, value-free diagnostic instead of letting
127	    // a raw exception — and whatever it might contain — propagate.
128	    return {
129	      ok: false,
130	      diagnostic: { code: "CONFIG_INVALID", process: "deploy", categories: ["runtime"], variables: [] },
131	      mode,
132	      apiEnv,
133	      webEnv,
134	      workerEnv,
135	      databaseEnv,
136	    };
137	  }
138	
139	  apiEnv.NODE_ENV = mode;
140	  webEnv.NODE_ENV = mode;
141	  workerEnv.NODE_ENV = mode;
142	  databaseEnv.NODE_ENV = mode;
143	
144	  return { ok: true, diagnostic: null, mode, apiEnv, webEnv, workerEnv, databaseEnv };
145	}
146	
147	function spawnAndWait(spawnFn, command, args, options) {
148	  return new Promise((resolve, reject) => {
149	    const child = spawnFn(command, args, options);
150	    child.on("error", reject);
151	    child.on("exit", (code, signal) => resolve(signal ? 1 : (code ?? 1)));
152	  });
153	}
154	
155	/**
156	 * Runs steps strictly in order and stops at the first nonzero result,
157	 * never invoking any later step. Pure orchestration with no knowledge of
158	 * what a step actually does — this is the seam tests use with injected
159	 * fake steps to prove ordering and failure propagation without running
160	 * any real build, migration, or process.
161	 */
162	export async function runSteps(steps) {
163	  for (const step of steps) {
164	    const exitCode = await step.run();
165	    if (exitCode !== 0) {
166	      return { ok: false, failedStep: step.name, exitCode };
167	    }
168	  }
169	  return { ok: true, failedStep: null, exitCode: 0 };
170	}
171	
172	export function createMigrateStep(target, env, options = {}) {
173	  const spawnFn = options.spawnFn ?? spawn;
174	  return {
175	    name: `migrate:${target}`,
176	    run: () =>
177	      spawnAndWait(spawnFn, process.execPath, [resolveTsxBin(), path.join(databaseDir, "src", "migrate.ts"), target], {
178	        stdio: "inherit",
179	        env,
180	        cwd: databaseDir,
181	      }),
182	  };
183	}
184	
185	export function createBuildStep(name, filterArgs, env, options = {}) {
186	  const spawnFn = options.spawnFn ?? spawn;
187	  return {
188	    name: `build:${name}`,
189	    run: () => spawnAndWait(spawnFn, "pnpm", filterArgs, { stdio: "inherit", shell: true, env, cwd: repoRoot }),
190	  };
191	}
192	
193	/**
194	 * Runs apps/worker to completion as a step (see the module docstring for
195	 * why it is not part of the supervised long-running service set).
196	 */
197	export function createWorkerStep(env, options = {}) {
198	  const spawnFn = options.spawnFn ?? spawn;
199	  return {
200	    name: "worker",
201	    run: () =>
202	      spawnAndWait(spawnFn, process.execPath, [path.join(workerDir, "dist", "main.js")], {
203	        stdio: "inherit",
204	        env,
205	        cwd: workerDir,
206	      }),
207	  };
208	}
209	
210	const DEFAULT_SHUTDOWN_GRACE_MS = 5000;
211	
212	/** Bounds how long a single termination COMMAND (not the whole shutdown) may run. */
213	const KILL_COMMAND_TIMEOUT_MS = 5000;
214	
215	/**
216	 * Kills `pid` AND every descendant IT directly owns, on both supported
217	 * platforms, targeting only that specific pid — never anything unrelated:
218	 *  - Windows: `taskkill /PID <pid> /T /F` walks the OS-maintained
219	 *    parent/child records and force-terminates the whole tree. This does
220	 *    not depend on the target cooperating with a signal at all, which
221	 *    matters because a plain `child.kill(signal)` on Windows only ever
222	 *    reaches the immediate child (never further descendants), and is not
223	 *    guaranteed to invoke a registered `process.on(signal)` handler in the
224	 *    target the way a real POSIX signal delivery would. IMPORTANT: this
225	 *    only works while `pid` is still alive — Windows cannot enumerate the
226	 *    children of a pid that has already exited (see `knownDescendantPids`
227	 *    below for how an already-dead pid's descendants are still reached).
228	 *  - POSIX: sends `signal` to the negative pid (the whole process group),
229	 *    which requires the child to have been spawned with `detached: true`
230	 *    (making it its own group leader). Unlike Windows, a POSIX process
231	 *    group ID remains valid for `kill(-pgid, ...)` as long as ANY member
232	 *    is still alive, even after the original leader has exited. Falls
233	 *    back to signaling the single pid if group-signaling fails (e.g. it
234	 *    was never a group leader).
235	 * The underlying OS command itself is bounded (`KILL_COMMAND_TIMEOUT_MS`)
236	 * so a hung `taskkill` can never leave this — or anything awaiting it —
237	 * pending forever; a command failure or timeout resolves `false` rather
238	 * than throwing, since callers separately CONFIRM the actual outcome by
239	 * polling liveness (see `waitForPidExit`) rather than trusting the
240	 * command's own reported success.
241	 */
242	function killPid(pid, signal) {
243	  return new Promise((resolve) => {
244	    if (process.platform === "win32") {
245	      execFile("taskkill", ["/pid", String(pid), "/T", "/F"], { timeout: KILL_COMMAND_TIMEOUT_MS }, (error) => {
246	        resolve(!error);
247	      });
248	      return;
249	    }
250	    try {
251	      process.kill(-pid, signal ?? "SIGKILL");
252	      resolve(true);
253	    } catch {
254	      try {
255	        process.kill(pid, signal ?? "SIGKILL");
256	        resolve(true);
257	      } catch {
258	        resolve(false); // already exited, or never existed
259	      }
260	    }
261	  });
262	}
263	
264	function isPidAlive(pid) {
265	  try {
266	    process.kill(pid, 0);
267	    return true;
268	  } catch {
269	    return false;
270	  }
271	}
272	
273	/**
274	 * Polls an ARBITRARY pid (one this process did not itself spawn, so there
275	 * is no ChildProcess object or "exit" event to listen for) until it is no
276	 * longer alive, or `timeoutMs` elapses. Used to CONFIRM that a descendant
277	 * reported over a service's own IPC channel has actually terminated,
278	 * rather than assuming a kill command's own reported success is enough.
279	 */
280	function waitForPidExit(pid, timeoutMs, intervalMs = 100) {
281	  if (!isPidAlive(pid)) return Promise.resolve(true);
282	  return new Promise((resolve) => {
283	    const start = Date.now();
284	    const timer = setInterval(() => {
285	      if (!isPidAlive(pid)) {
286	        clearInterval(timer);
287	        resolve(true);
288	      } else if (Date.now() - start >= timeoutMs) {
289	        clearInterval(timer);
290	        resolve(false);
291	      }
292	    }, intervalMs);
293	  });
294	}
295	
296	/**
297	 * The default spawnFn used by startAndSupervise:
298	 *  - Spawns detached on POSIX (so the child becomes its own process-group
299	 *    leader and `killPid` can target the whole group even after the
300	 *    leader itself has exited) — a no-op distinction on Windows, where
301	 *    tree relationships are tracked by the OS regardless of `detached`.
302	 *  - Adds a 4th ("ipc") stdio slot alongside whatever the caller asked
303	 *    for, so a Node.js service can optionally report a descendant pid it
304	 *    owns via `process.send({ type: "descendant-pid", pid })` — see
305	 *    `startAndSupervise`'s `knownDescendantPids` tracking below. A service
306	 *    that never calls `process.send` is entirely unaffected.
307	 */
308	function defaultSpawnService(command, args, options) {
309	  const requestedStdio = options.stdio ?? "inherit";
310	  const baseStdio = Array.isArray(requestedStdio) ? requestedStdio : [requestedStdio, requestedStdio, requestedStdio];
311	  const spawnOptions = {
312	    ...options,
313	    stdio: [...baseStdio, "ipc"],
314	    ...(process.platform === "win32" ? {} : { detached: true }),
315	  };
316	  return spawn(command, args, spawnOptions);
317	}
318	
319	/** Waits for a CHILD PROCESS THIS FUNCTION SPAWNED to emit "exit", bounded by `timeoutMs`. */
320	function waitForChildExit(child, timeoutMs) {
321	  if (child.exitCode !== null || child.signalCode !== null) {
322	    return Promise.resolve(true);
323	  }
324	  return new Promise((resolve) => {
325	    const onExit = () => {
326	      clearTimeout(timer);
327	      resolve(true);
328	    };
329	    const timer = setTimeout(() => {
330	      child.off("exit", onExit);
331	      resolve(false);
332	    }, timeoutMs);
333	    child.once("exit", onExit);
334	  });
335	}
336	
337	/** Bounds how many times a still-alive descendant pid is forcefully re-killed before giving up on it. */
338	const MAX_DESCENDANT_KILL_ATTEMPTS = 2;
339	
340	/**
341	 * Forces an arbitrary (already-spawned, possibly parent-less) pid to exit,
342	 * confirming the outcome by polling liveness rather than trusting a single
343	 * kill command's own reported success — a hung or ignored kill command must
344	 * not be mistaken for a clean exit. Bounded to `MAX_DESCENDANT_KILL_ATTEMPTS`
345	 * so a stuck pid can never keep the caller waiting indefinitely; returns
346	 * whether the pid was actually confirmed gone.
347	 */
348	async function ensurePidGone(pid, killFn, gracePeriodMs) {
349	  if (!isPidAlive(pid)) return true;
350	  for (let attempt = 0; attempt < MAX_DESCENDANT_KILL_ATTEMPTS; attempt++) {
351	    await killFn(pid, "SIGKILL");
352	    if (await waitForPidExit(pid, gracePeriodMs)) return true;
353	  }
354	  return !isPidAlive(pid);
355	}
356	
357	/**
358	 * Spawns every service and supervises the group's lifecycle:
359	 *  - If one fails to spawn (including a synchronous spawn exception) or
360	 *    exits unexpectedly (before a requested shutdown), every service —
361	 *    including the one that failed — and everything each one owns is
362	 *    terminated, and the returned promise resolves nonzero only AFTER
363	 *    every owned process has been confirmed to have actually exited (not
364	 *    merely "asked to").
365	 *  - A requested shutdown (`requestShutdown`, wired to SIGINT/SIGTERM by
366	 *    the caller) terminates every service the same way and resolves 0
367	 *    once cleanup is confirmed complete — never 0 if any owned process
368	 *    could not be confirmed gone.
369	 *  - Termination of a service's DIRECT process is bounded, in two steps,
370	 *    and the second step ALWAYS runs regardless of how the first went:
371	 *    (1) a cooperative signal (`child.kill(signal)`), giving a
372	 *    well-behaved process — including apps/web's wrapper, which forwards
373	 *    it to its own Next child — a chance to shut down its own tree on its
374	 *    own, bounded by `gracePeriodMs`; then (2) an unconditional,
375	 *    platform-appropriate tree-kill (`killFn`) targeting the same pid.
376	 *    Step 2 is not an "if step 1 failed" escalation: a direct child can
377	 *    appear to exit immediately (on Windows, a non-SIGKILL signal
378	 *    terminates the direct child outright, before it can forward anything
379	 *    to what it spawned) while still leaving a descendant it owns running.
380	 *  - Independently of the direct process's own exit status — including a
381	 *    direct process that already exited on its own, unexpectedly, before
382	 *    termination was ever requested — every pid a service has reported
383	 *    via its own IPC channel (`process.send({ type: "descendant-pid", pid
384	 *    })`, e.g. apps/web/scripts/run.mjs's Next child) is force-killed and
385	 *    its exit confirmed too. A dead parent's pid is never assumed
386	 *    sufficient to find or identify its descendants: only pids a service
387	 *    itself has reported are ever targeted this way, exactly the
388	 *    "appropriate mechanism" available on both platforms without a new
389	 *    dependency or unreliable process enumeration of an already-dead
390	 *    parent (Windows cannot enumerate a dead pid's children at all; a
391	 *    reported pid sidesteps that limitation entirely).
392	 *  - Never signals anything beyond the specific pids this function itself
393	 *    spawned or was explicitly told about (and their process groups on
394	 *    POSIX) — no broad or name-based process lookup is ever used.
395	 *
396	 * `options.spawnFn` is injectable so tests can simulate spawn failures
397	 * without depending on a specific missing executable; `options.killFn` is
398	 * injectable so lifecycle-ordering tests can observe termination calls
399	 * without real process trees, while separate tests use the real `killPid`
400	 * against harmless local fixtures to prove actual OS-level cleanup.
401	 */
402	export function startAndSupervise(services, options = {}) {
403	  const spawnFn = options.spawnFn ?? defaultSpawnService;
404	  const killFn = options.killFn ?? killPid;
405	  const gracePeriodMs = options.gracePeriodMs ?? DEFAULT_SHUTDOWN_GRACE_MS;
406	
407	  const entries = new Map();
408	  let finalCode = 0;
409	  let cleanupFailed = false;
410	  let settled = false;
411	  let terminationPromise = null;
412	  let resolveExit;
413	  const exitPromise = new Promise((resolve) => {
414	    resolveExit = resolve;
415	  });
416	
417	  function settle(code) {
418	    if (settled) return;
419	    settled = true;
420	    resolveExit(code);
421	  }
422	
423	  /**
424	   * Terminates one entry's OWNED TREE: its direct process (if not already
425	   * exited) AND every descendant pid it has ever reported, regardless of
426	   * whether the direct process is currently alive, already exited
427	   * cooperatively, or already exited unexpectedly. Never throws — a
428	   * failure to confirm cleanup is recorded (`cleanupFailed`) and logged,
429	   * never silently treated as success.
430	   */
431	  async function terminate(entry, signal) {
432	    const { child } = entry;
433	    let directConfirmed = true;
434	
435	    if (child !== null && !entry.exited) {
436	      const pid = child.pid;
437	
438	      if (process.platform === "win32") {
439	        // See killPid's docstring: run the guaranteed tree-kill FIRST,
440	        // while the process (and its recorded parent/child relationships)
441	        // still exist, since a plain signal can terminate the direct
442	        // child immediately without it ever forwarding anything onward.
443	        if (pid !== undefined) {
444	          directConfirmed = await killFn(pid, "SIGKILL");
445	        }
446	        if (child.exitCode === null && child.signalCode === null) {
447	          try {
448	            child.kill(signal ?? "SIGTERM");
449	          } catch {
450	            /* already gone */
451	          }
452	        }
453	        const exited = await waitForChildExit(child, gracePeriodMs);
454	        directConfirmed = directConfirmed && exited;
455	      } else {
456	        // POSIX: signal the whole process group (this child was spawned
457	        // as its own group leader — see defaultSpawnService) first, so a
458	        // well-behaved process AND everything it owns gets a genuine
459	        // chance to shut down cooperatively.
460	        if (child.exitCode === null && child.signalCode === null) {
461	          try {
462	            process.kill(-pid, signal ?? "SIGTERM");
463	          } catch {
464	            try {
465	              child.kill(signal ?? "SIGTERM");
466	            } catch {
467	              /* already gone */
468	            }
469	          }
470	        }
471	        let exited = await waitForChildExit(child, gracePeriodMs);
472	        if (!exited && pid !== undefined) {
473	          await killFn(pid, "SIGKILL");
474	          exited = await waitForChildExit(child, gracePeriodMs);
475	        }
476	        directConfirmed = exited;
477	      }
478	      entry.exited = true;
479	    }
480	
481	    // Independently of the direct process's fate: clean up every
482	    // descendant this service ever told us about. This is what reaches a
483	    // wrapper's still-alive child even when the wrapper itself already
484	    // exited (cooperatively or not) before this ran.
485	    let descendantsConfirmed = true;
486	    for (const descendantPid of entry.knownDescendantPids) {
487	      const gone = await ensurePidGone(descendantPid, killFn, gracePeriodMs);
488	      if (!gone) descendantsConfirmed = false;
489	    }
490	
491	    if (!directConfirmed || !descendantsConfirmed) {
492	      cleanupFailed = true;
493	      console.error(JSON.stringify({ code: "SERVICE_CLEANUP_FAILED", service: entry.name }));
494	    }
495	  }
496	
497	  /**
498	   * Starts (idempotently) terminating every owned tree and settles
499	   * `exitPromise` only once every one of them has been awaited — never on
500	   * the mere firing of a direct child's "exit" event. Safe to call
501	   * repeatedly (a requested shutdown racing an unexpected exit, or
502	   * multiple signals) — every call after the first returns the same
503	   * in-flight promise instead of starting a redundant, overlapping
504	   * termination pass.
505	   */
506	  function beginTermination(signal) {
507	    if (terminationPromise) return terminationPromise;
508	    terminationPromise = Promise.all([...entries.values()].map((entry) => terminate(entry, signal)))
509	      .then(() => {
510	        settle(cleanupFailed ? finalCode || 1 : finalCode);
511	      })
512	      .catch((error) => {
513	        console.error(
514	          JSON.stringify({ code: "SUPERVISOR_CLEANUP_ERROR", message: error instanceof Error ? error.message : String(error) }),
515	        );
516	        settle(finalCode || 1);
517	      });
518	    return terminationPromise;
519	  }
520	
521	  // A synchronous spawn exception must still tear down every OTHER
522	  // service, including ones not yet spawned at the point of the throw —
523	  // so termination is deferred until every entry exists in `entries`,
524	  // rather than started immediately mid-loop (which would silently omit
525	  // any later service from the termination pass entirely).
526	  let hasSyncSpawnFailure = false;
527	
528	  for (const service of services) {
529	    const entry = { name: service.name, child: null, exited: false, knownDescendantPids: new Set() };
530	    entries.set(service.name, entry);
531	
532	    let child;
533	    try {
534	      child = spawnFn(service.command, service.args, {
535	        stdio: service.stdio ?? "inherit",
536	        env: service.env,
537	        cwd: service.cwd,
538	      });
539	    } catch {
540	      // A synchronous spawn exception leaves no ChildProcess to wait on or
541	      // signal at all — otherwise identical to an async "error" event.
542	      console.error(JSON.stringify({ code: "SERVICE_SPAWN_FAILED", service: service.name }));
543	      entry.exited = true;
544	      finalCode = finalCode || 1;
545	      hasSyncSpawnFailure = true;
546	      continue;
547	    }
548	    entry.child = child;
549	
550	    if (typeof child.on === "function") {
551	      child.on("message", (message) => {
552	        if (message && message.type === "descendant-pid" && typeof message.pid === "number") {
553	          entry.knownDescendantPids.add(message.pid);
554	        }
555	      });
556	    }
557	
558	    child.once("error", () => {
559	      console.error(JSON.stringify({ code: "SERVICE_SPAWN_FAILED", service: service.name }));
560	      entry.exited = true; // an async spawn error means there is no real process to wait for
561	      finalCode = finalCode || 1;
562	      void beginTermination();
563	    });
564	
565	    child.once("exit", (code) => {
566	      const wasAlreadyShuttingDown = terminationPromise !== null;
567	      entry.exited = true;
568	      if (!wasAlreadyShuttingDown) {
569	        console.error(JSON.stringify({ code: "SERVICE_EXITED_UNEXPECTEDLY", service: service.name }));
570	        finalCode = code && code !== 0 ? code : 1;
571	        void beginTermination();
572	      }
573	    });
574	  }
575	
576	  if (services.length === 0) {
577	    settle(0); // degenerate case: nothing to supervise or ever terminate
578	  } else if (hasSyncSpawnFailure) {
579	    void beginTermination();
580	  }
581	
582	  function requestShutdown(signal) {
583	    void beginTermination(signal);
584	    return exitPromise;
585	  }
586	
587	  return { exitPromise, requestShutdown };
588	}
589	
590	function isMainModule() {
591	  const entry = process.argv[1];
592	  return entry !== undefined && import.meta.url === pathToFileURL(entry).href;
593	}
594	
595	async function main() {
596	  const args = process.argv.slice(2);
597	  const skipMigrate = args.includes("--skip-migrate");
598	  const skipBuild = args.includes("--skip-build");
599	  const skipWorker = args.includes("--skip-worker");
600	
601	  const validation = validateDeployment(process.env, { skipMigrate });
602	  if (!validation.ok) {
603	    console.error(JSON.stringify(validation.diagnostic));
604	    process.exit(1);
605	  }
606	
607	  const { apiEnv, webEnv, workerEnv, databaseEnv } = validation;
608	
609	  const steps = [];
610	  if (!skipMigrate) {
611	    // databaseEnv was already resolved (root/package env-file precedence)
612	    // AND validated above — including its CONTROL_DATABASE_URL and its
613	    // NODE_ENV forced to the same `mode` — so it is passed through
614	    // unchanged. Raw process.env is never re-read here.
615	    steps.push(createMigrateStep("control", databaseEnv));
616	  }
617	  if (!skipBuild) {
618	    steps.push(createBuildStep("api", ["--filter", "./apps/api", "build"], apiEnv));
619	    steps.push(createBuildStep("worker", ["--filter", "@relis/worker", "build"], workerEnv));
620	    steps.push(createBuildStep("web", ["--filter", "./apps/web", "build"], webEnv));
621	  }
622	  if (!skipWorker) {
623	    steps.push(createWorkerStep(workerEnv));
624	  }
625	
626	  const stepResult = await runSteps(steps);
627	  if (!stepResult.ok) {
628	    console.error(JSON.stringify({ code: "DEPLOY_STEP_FAILED", step: stepResult.failedStep }));
629	    process.exit(stepResult.exitCode);
630	  }
631	
632	  // Only api and web are genuinely long-running; see the module docstring
633	  // for why apps/worker is a completing step above instead.
634	  const services = [
635	    { name: "api", command: process.execPath, args: [path.join(apiDir, "dist", "main.js")], env: apiEnv, cwd: apiDir },
636	    {
637	      name: "web",
638	      command: process.execPath,
639	      args: [path.join(webDir, "scripts", "run.mjs"), "start"],
640	      env: webEnv,
641	      cwd: webDir,
642	    },
643	  ];
644	
645	  const supervisor = startAndSupervise(services);
646	  process.on("SIGINT", () => supervisor.requestShutdown("SIGINT"));
647	  process.on("SIGTERM", () => supervisor.requestShutdown("SIGTERM"));
648	
649	  const exitCode = await supervisor.exitPromise;
650	  process.exit(exitCode);
651	}
652	
653	if (isMainModule()) {
654	  main();
655	}
