6	/**
7	 * Checks whether the `docker` CLI is present AND a daemon is reachable.
8	 * Integration tests that require a real container runtime must gate on
9	 * this and report a skip — never fabricate a pass, and never fall back
10	 * to a mock, when it is false. See
11	 * docs/architecture/docker-compose-stack.md and this sub-issue's
12	 * "Tests and verification" boundary.
13	 */
14	export async function isDockerAvailable(): Promise<boolean> {
15	  try {
16	    const result = await runToCompletion("docker", ["info", "--format", "{{.ServerVersion}}"], { timeoutMs: 10000 });
17	    return result.exitCode === 0;
18	  } catch {
19	    return false;
20	  }
21	}
22	
23	/**
24	 * Synchronous equivalent of `isDockerAvailable`, for use at MODULE scope
25	 * (e.g. `const dockerAvailable = isDockerAvailableSync();` at the top of
26	 * a test file) so the result can gate `describe.runIf`/`skipIf`.
27	 * Vitest collects a test file by running it top-to-bottom once BEFORE any
28	 * `beforeAll` hook body executes, so an async check stored in a
29	 * `beforeAll` is always still `false` at the point `describe.runIf` reads
30	 * it — this sync check exists specifically to avoid that trap.
31	 */
32	export function isDockerAvailableSync(): boolean {
33	  try {
34	    execFileSync("docker", ["info", "--format", "{{.ServerVersion}}"], { timeout: 10000, stdio: "ignore" });
35	    return true;
36	  } catch {
37	    return false;
38	  }
39	}
40	
41	/** A short, random suffix keeps parallel/leftover test runs from colliding on project name. */
42	export function uniqueProjectName(prefix: string): string {
43	  return `${prefix}-${randomBytes(4).toString("hex")}`;
44	}
45	
46	/**
47	 * Finds a currently-free TCP port on loopback by briefly binding to port
48	 * 0 and reading back the OS-assigned port, then releasing it
49	 * immediately.
50	 *
51	 * This exists specifically for NGINX_HTTP_PORT, and must NOT be confused
52	 * with the "pass 0, discover the real port with `composePort` afterward"
53	 * pattern used for MAILHOG_UI_PORT/SEAWEEDFS_S3_PORT: those two variables
54	 * are never read by any application code, so discovering the real port
55	 * AFTER `docker compose up` is fine. NGINX_HTTP_PORT is different — it is
56	 * baked directly into `NEXT_PUBLIC_API_URL` on the `web` service at
57	 * container start (see docker-compose.yml). Passing the literal string
58	 * "0" there bakes the broken value "http://localhost:0/api" into the
59	 * running container; the real port must be known BEFORE `docker compose
60	 * up` runs, which is what this function is for.
61	 *
62	 * Has the usual small TOCTOU race (another process could claim the port
63	 * between this closing it and Compose binding it) — an accepted
64	 * trade-off for a disposable local test run, same as any "find a free
65	 * port" test helper.
66	 */
67	export async function getFreePort(): Promise<number> {
68	  return new Promise((resolve, reject) => {
69	    const server = createServer();
70	    server.unref();
71	    server.on("error", reject);
72	    server.listen(0, "127.0.0.1", () => {
73	      const address = server.address();
74	      if (address === null || typeof address === "string") {
75	        server.close();
76	        reject(new Error("Could not determine an assigned port"));
77	        return;
78	      }
79	      const { port } = address;
80	      server.close(() => resolve(port));
81	    });
82	  });
83	}
