85	export interface ComposeProject {
86	  /** Unique per test run — scopes every container/network/volume Compose creates (`docker compose -p`). */
87	  projectName: string;
88	  /** Path to docker-compose.yml. */
89	  composeFile: string;
90	  /** Directory to run `docker compose` from (the repository root). */
91	  cwd: string;
92	}
93	
94	export type ComposeEnv = Record<string, string>;
95	
96	function composeArgs(project: ComposeProject, rest: string[]): string[] {
97	  return ["compose", "-p", project.projectName, "-f", project.composeFile, ...rest];
98	}
99	
100	function withEnv(env: ComposeEnv): NodeJS.ProcessEnv {
101	  return { ...process.env, ...env };
102	}
