104	/**
105	 * Brings up the stack (or a subset of `services`) for `project`. Callers
106	 * are responsible for calling `cleanupComposeProject` (preferred — it
107	 * throws on a cleanup failure instead of silently ignoring it) or
108	 * `composeDown` on the SAME project afterward — this never touches any
109	 * other Compose project, container, or volume (Compose namespaces
110	 * everything by `-p` project name). Note that `composeRun` (below) also
111	 * implicitly creates the project's network, even though its container is
112	 * removed by `--rm` — cleanup is required after using it too, not only
113	 * after `composeUp`.
114	 */
115	export async function composeUp(
116	  project: ComposeProject,
117	  env: ComposeEnv,
118	  services: string[] = [],
119	  options: { build?: boolean; timeoutMs?: number } = {},
120	): Promise<SpawnResult> {
121	  const args = composeArgs(project, ["up", "-d"]);
