330	/**
331	 * Polls `url` with plain HTTP GET requests until a response's status code
332	 * satisfies `isAcceptable`, or `timeoutMs` elapses — unlike `waitForHttpOk`
333	 * (which accepts ANY status, including a failure one, as "the server is
334	 * accepting connections"), this is for a BOUNDED wait on a specific
335	 * outcome, e.g. "the proxy reports success again after its upstream was
336	 * restored." Returns the accepted `Response` so the caller can inspect its
337	 * body without a second request.
338	 *
339	 * Genuinely bounded by `timeoutMs` overall, not merely "checked between
340	 * requests": each individual `fetch` is given an `AbortController` tied to
341	 * the REMAINING time left in the overall deadline (`deadline - Date.now()`
342	 * at the moment that request starts), not a fresh `timeoutMs` of its own —
343	 * a single pending request (e.g. a proxy that has silently dropped
344	 * packets toward a dead upstream, with no reply at all) can therefore
345	 * never push the total wait past `timeoutMs`. The retry delay between
346	 * attempts is likewise clamped to whatever remains of the deadline, never
347	 * a fixed delay that could itself overshoot it.
348	 *
349	 * Every REJECTED response's body is explicitly released
350	 * (`response.body?.cancel()`) before the next attempt — this is not a
351	 * cosmetic cleanup: an un-drained response body can otherwise stall a
352	 * kept-alive connection's reuse by the HTTP client on the very next
353	 * request. The ACCEPTED response is returned untouched — its body is
354	 * never read or cancelled here — so the caller can still consume it
355	 * exactly once.
356	 */
357	export async function waitForHttpStatus(
358	  url: string,
359	  isAcceptable: (status: number) => boolean,
360	  timeoutMs = 60000,
361	): Promise<Response> {
362	  const deadline = Date.now() + timeoutMs;
363	  let lastStatus: number | undefined;
364	  let lastError: unknown;
365	
366	  for (;;) {
367	    const remaining = deadline - Date.now();
368	    if (remaining <= 0) break;
369	
370	    const controller = new AbortController();
371	    const abortTimer = setTimeout(() => controller.abort(), remaining);
372	    try {
373	      const response = await fetch(url, { signal: controller.signal });
374	      if (isAcceptable(response.status)) {
375	        return response;
376	      }
377	      lastStatus = response.status;
378	      // Not the response we're waiting for — release it (see doc comment
379	      // above) rather than leaving its body unconsumed.
380	      try {
381	        await response.body?.cancel();
382	      } catch {
383	        // Already closed/errored; nothing left to release.
384	      }
385	    } catch (error) {
386	      lastError = error;
387	    } finally {
388	      clearTimeout(abortTimer);
389	    }
390	
391	    const retryDelay = Math.min(1000, deadline - Date.now());
392	    if (retryDelay <= 0) break;
393	    await new Promise((resolveDelay) => setTimeout(resolveDelay, retryDelay));
394	  }
395	  throw new Error(
396	    `Timed out after ${timeoutMs}ms waiting for ${url} to reach an acceptable status. ` +
397	      `Last observed status: ${lastStatus ?? "(none — request never completed)"}. Last error: ${String(lastError)}`,
398	  );
399	}
