526	/**
527	 * `docker volume inspect` for one volume.
528	 *
529	 * Returns `undefined` ONLY for a genuine "no such volume" response (see
530	 * `isVolumeNotFoundError`) — never for any other nonzero exit. A daemon
531	 * that is unreachable, a permission failure, or any other command
532	 * failure THROWS instead, naming the exit code and stderr. Malformed
533	 * output on a zero exit (unparseable JSON) also throws rather than being
534	 * swallowed. This matters specifically because `volumeExists` (below)
535	 * delegates to this function: without this distinction, an inspection
536	 * FAILURE could silently read as "the volume does not exist," which
537	 * would let a caller wrongly treat a failed check as proof a volume was
538	 * deleted.
539	 */
540	export async function inspectVolume(name: string): Promise<VolumeOwnership | undefined> {
541	  const result = await runToCompletion("docker", ["volume", "inspect", name, "--format", "{{json .}}"], { timeoutMs: 30000 });
542	  if (result.exitCode !== 0) {
543	    if (isVolumeNotFoundError(result.stderr)) return undefined;
544	    throw new Error(
545	      `docker volume inspect "${name}" failed (exit ${result.exitCode}) and is NOT a "no such volume" response — ` +
546	        `refusing to treat this as absence:\nstderr:\n${result.stderr}\nstdout:\n${result.stdout}`,
547	    );
548	  }
549	  let raw: { Name: string; Driver: string; Labels: Record<string, string> | null };
550	  try {
551	    raw = JSON.parse(result.stdout.trim()) as { Name: string; Driver: string; Labels: Record<string, string> | null };
552	  } catch (error) {
553	    throw new Error(
554	      `docker volume inspect "${name}" exited 0 but its output could not be parsed as JSON: ${String(error)}\nstdout:\n${result.stdout}`,
555	    );
556	  }
557	  const labels = raw.Labels ?? {};
558	  return {
559	    name: raw.Name,
560	    driver: raw.Driver,
561	    composeProject: labels["com.docker.compose.project"],
562	    composeVolumeKey: labels["com.docker.compose.volume"],
563	    labels,
564	  };
565	}
