595	/**
596	 * The three — and only three — outcomes inspecting one volume name can
597	 * have, kept explicitly distinct so a destructive gate can never
598	 * confuse one for another:
599	 *   - `"exists"` — the volume is really there, with its real ownership.
600	 *   - `"absent"` — the daemon CONFIRMED no such volume exists (see
601	 *     `isVolumeNotFoundError`). There is nothing to delete and nothing
602	 *     to protect: this must never block a destructive step.
603	 *   - `"failed"` — inspecting it did not succeed at all (daemon
604	 *     unreachable, permission denied, malformed output — see
605	 *     `inspectVolume`'s own contract). This is NOT the same as absence
606	 *     and MUST block a destructive step: the volume could exist and we
607	 *     simply don't know.
608	 */
609	export type VolumeInspectionResult =
610	  | { status: "exists"; ownership: VolumeOwnership }
611	  | { status: "absent" }
612	  | { status: "failed"; error: string };
