620	/**
621	 * Pure ownership gate for ONE volume, given an already-fetched
622	 * inspection result: it never queries the daemon itself, which is what
623	 * makes it independently unit-testable with constructed fakes (no real
624	 * Docker, no risk to any real volume).
625	 *
626	 * - `"absent"` is always `ok: true` — a CONFIRMED absence is not a
627	 *   reason to block anything; there is simply nothing there to delete.
628	 * - `"failed"` is always `ok: false` — an inspection FAILURE must never
629	 *   be treated as "safe to proceed," because the volume might still be
630	 *   there.
631	 * - `"exists"` is `ok: true` only when ALL of: the volume is NOT in
632	 *   `context.baselineVolumeNames` (it did not already exist before this
633	 *   run); its `com.docker.compose.project` label matches
634	 *   `context.expectedProjectName` exactly (it belongs to THIS disposable
635	 *   project, not a development stack or another project, and never a
636	 *   name-prefix guess); and its `com.docker.compose.volume` key is not
637	 *   one of `context.externalVolumeKeys` (not declared `external: true`,
638	 *   which would make it a pre-existing resource regardless of its
639	 *   labels).
640	 */
641	export function checkVolumeOwnershipForDeletion(
642	  name: string,
643	  inspection: VolumeInspectionResult,
644	  context: VolumeOwnershipContext,
645	): VolumeDeletionCheck {
646	  if (inspection.status === "absent") {
647	    return { name, ok: true };
648	  }
649	  if (inspection.status === "failed") {
650	    return { name, ok: false, reason: `could not be inspected: ${inspection.error}` };
651	  }
652	  const { ownership } = inspection;
653	  if (context.baselineVolumeNames.includes(name)) {
654	    return { name, ok: false, reason: "already existed on the daemon before this run started — it is a pre-existing resource" };
655	  }
656	  if (ownership.composeProject !== context.expectedProjectName) {
657	    return {
658	      name,
659	      ok: false,
660	      reason:
661	        `labelled com.docker.compose.project="${ownership.composeProject ?? "(none)"}", not the expected disposable ` +
662	        `project "${context.expectedProjectName}" — it may belong to a development stack or another user resource`,
663	    };
664	  }
665	  if (ownership.composeVolumeKey !== undefined && context.externalVolumeKeys.includes(ownership.composeVolumeKey)) {
666	    return {
667	      name,
668	      ok: false,
669	      reason: `implements volume key "${ownership.composeVolumeKey}", declared external:true — a pre-existing user resource`,
670	    };
671	  }
672	  return { name, ok: true };
673	}
