680	/**
681	 * The hard gate a destructive reset or cleanup must pass before
682	 * `--volumes` is ever issued: PURE and synchronous — it only classifies
683	 * already-fetched `records` (see `discoverVolumesRequiringInspection`
684	 * for how those are built), which is what makes it independently
685	 * unit-testable with constructed fakes. `ok` is true only when EVERY
686	 * record passes `checkVolumeOwnershipForDeletion`. An EMPTY `records`
687	 * list is itself refused — there is nothing to establish ownership of,
688	 * which must never be read as "nothing to check, proceed."
689	 */
690	export function evaluateOwnershipGate(records: readonly OwnedVolumeRecord[], context: VolumeOwnershipContext): OwnershipGateResult {
691	  if (records.length === 0) {
692	    return {
693	      ok: false,
694	      checks: [{ name: "(none)", ok: false, reason: "no volume was identified for this project — ownership cannot be established" }],
695	    };
696	  }
697	  const checks = records.map((record) => checkVolumeOwnershipForDeletion(record.name, record.inspection, context));
698	  return { ok: checks.every((check) => check.ok), checks };
699	}
