701	export interface VolumeDiscoverySources {
702	  /**
703	   * The EXACT volume names `docker compose down --volumes` would target
704	   * for this project — i.e. a FRESH read of `resolveComposePersistence`'s
705	   * `volumeNames` values, using the SAME Compose file/project/env the
706	   * destructive step itself will use. MUST reject (never resolve to a
707	   * partial or stale list) when the configuration cannot be resolved —
708	   * `discoverVolumesRequiringInspection` propagates that rejection so
709	   * the caller fails closed.
710	   */
711	  resolveConfiguredVolumeNames: () => Promise<string[]>;
712	  /** Volume names the daemon's own `com.docker.compose.project` label filter reports for this project (e.g. `listVolumeNamesByComposeProject`). */
713	  listLabeledVolumeNames: () => Promise<string[]>;
714	  /** Inspects one volume name. Resolves to `undefined` ONLY for a CONFIRMED absence; any other failure must throw (see `inspectVolume`'s own contract). */
715	  inspectVolumeByName: (name: string) => Promise<VolumeOwnership | undefined>;
716	}
