718	/**
719	 * Builds the full, de-duplicated set of volume names that MUST be
720	 * inspected before a destructive cleanup, and inspects every one.
721	 *
722	 * The set is the UNION of:
723	 *   - the volume names resolved from the EXACT Compose configuration the
724	 *     destructive step will use (`resolveConfiguredVolumeNames`) — this
725	 *     is what `docker compose down --volumes` actually targets, by
726	 *     NAME; and
727	 *   - whatever the daemon's own project-LABEL filter additionally
728	 *     reports (`listLabeledVolumeNames`).
729	 * Label-based discovery ALONE is not enough to gate a destructive step:
730	 * a volume whose NAME matches what Compose will target, but whose
731	 * `com.docker.compose.project` label is missing or wrong (created
732	 * out-of-band, relabeled, or a Compose/engine quirk), would never
733	 * appear in a label-filtered list — yet `docker compose down --volumes`
734	 * addresses volumes by NAME, not by label, and would still remove it.
735	 * The union closes exactly that gap.
736	 *
737	 * FAILS CLOSED: if EITHER `resolveConfiguredVolumeNames` or
738	 * `listLabeledVolumeNames` rejects, this rejects too, rather than
739	 * silently proceeding with whichever half succeeded — an INCOMPLETE
740	 * name set must never be treated as "nothing else to check." (Callers
741	 * such as `cleanupDisposableTargets` catch this and block the
742	 * destructive step for that target entirely, reporting the failure.)
743	 *
744	 * A single name's OWN inspection failure, by contrast, does NOT abort
745	 * this whole function: once the complete name set is known, every name
746	 * is inspected independently, and a failure for one is recorded as that
747	 * record's own `{status:"failed"}` (see `VolumeInspectionResult`) so
748	 * every other volume's real status is still reported — never silently
749	 * dropped, and never confused with a confirmed `"absent"`.
750	 */
751	export async function discoverVolumesRequiringInspection(sources: VolumeDiscoverySources): Promise<OwnedVolumeRecord[]> {
752	  const [configuredNames, labeledNames] = await Promise.all([sources.resolveConfiguredVolumeNames(), sources.listLabeledVolumeNames()]);
753	  const unionNames = Array.from(new Set([...configuredNames, ...labeledNames]));
754	  return Promise.all(
755	    unionNames.map(async (name): Promise<OwnedVolumeRecord> => {
756	      try {
757	        const ownership = await sources.inspectVolumeByName(name);
758	        return { name, inspection: ownership ? { status: "exists", ownership } : { status: "absent" } };
759	      } catch (error) {
760	        return { name, inspection: { status: "failed", error: String(error) } };
761	      }
762	    }),
763	  );
764	}
