771	/**
772	 * Validates a RESOLVED Compose configuration is safe to provision as a
773	 * disposable project — called BEFORE any container or volume is
774	 * created, using only the static `docker compose config` output (no
775	 * daemon query, which is what makes this pure and unit-testable with a
776	 * constructed `ResolvedComposePersistence`). Every declared volume must:
777	 *   - Resolve to a name actually prefixed by the project's own name
778	 *     (`<project>_<key>` or `<project>-<key>`), so it cannot collide
779	 *     with a different project's volume.
780	 *   - Not be declared `external: true` — that would point at a
781	 *     pre-existing user resource this stack must never create or
782	 *     destroy.
783	 *   - Not already exist on the daemon (the pre-captured baseline) —
784	 *     catches the one scenario volume-name-prefixing alone cannot: a
785	 *     volume that, by coincidence or a reused project name, already
786	 *     exists under the exact name this run is about to use.
787	 */
788	export function checkProvisioningSafety(
789	  resolved: ResolvedComposePersistence,
790	  baselineVolumeNames: readonly string[],
791	): ProvisioningSafetyCheck {
792	  const problems: string[] = [];
793	  if (resolved.externalVolumes.length > 0) {
794	    problems.push(`volume key(s) declared external:true: ${resolved.externalVolumes.join(", ")} — refusing a pre-existing resource`);
795	  }
796	  for (const [key, name] of Object.entries(resolved.volumeNames)) {
797	    if (!name.startsWith(`${resolved.projectName}_`) && !name.startsWith(`${resolved.projectName}-`)) {
798	      problems.push(`volume "${name}" (key "${key}") is not scoped to project "${resolved.projectName}" by name`);
799	    }
800	    if (baselineVolumeNames.includes(name)) {
801	      problems.push(`volume "${name}" (key "${key}") already exists on the daemon before this run started`);
802	    }
803	  }
804	  return { ok: problems.length === 0, problems };
805	}
