807	/** `checkProvisioningSafety`, but throws — stopping short of provisioning anything — when the check fails. */
808	export function assertProvisioningSafety(resolved: ResolvedComposePersistence, baselineVolumeNames: readonly string[]): void {
809	  const check = checkProvisioningSafety(resolved, baselineVolumeNames);
810	  if (!check.ok) {
811	    throw new Error(`Refusing to provision disposable project "${resolved.projectName}":\n- ${check.problems.join("\n- ")}`);
812	  }
813	}
