833	export interface DisposableCleanupTarget {
834	  /** Identifies this target in a reported outcome — typically the Compose project name. */
835	  label: string;
836	  /**
837	   * Produces the full set of volumes requiring inspection for this
838	   * target (see `discoverVolumesRequiringInspection` — the union of the
839	   * exact configured names and whatever label-based discovery reports,
840	   * each already paired with its inspection result). Resolving this
841	   * here, rather than inside `cleanupDisposableTargets` itself, is what
842	   * keeps that function's own decision logic pure and independently
843	   * unit-testable with constructed fakes — no real Docker call is
844	   * hard-wired into it. MUST reject (fail closed) rather than resolve
845	   * to a partial list when the underlying configuration cannot be
846	   * resolved — see `discoverVolumesRequiringInspection`'s own contract.
847	   */
848	  discoverVolumes: () => Promise<OwnedVolumeRecord[]>;
849	  /** Context used to verify EVERY discovered volume immediately before any is destroyed. */
850	  ownershipContext: VolumeOwnershipContext;
851	  /** Removes this target's containers/network but KEEPS its volumes. Always safe to call: it never touches another target's resources, and never deletes data. */
852	  removeContainersKeepingVolumes: () => Promise<void>;
853	  /** Removes this target's containers/network AND its named volumes. Only ever invoked by `cleanupDisposableTargets` after every discovered volume has passed the ownership gate. */
854	  removeContainersAndVolumes: () => Promise<void>;
