857	export interface DisposableCleanupOutcome {
858	  label: string;
859	  volumesDeleted: string[];
860	  volumesRequiringManualInspection: { name: string; reason: string }[];
861	  /** Set when something about processing this target itself failed (discovering its volumes, or either removal call) — includes a failed/fail-closed configuration resolution. */
862	  error?: string;
863	}
