865	/**
866	 * Cleans up multiple disposable targets independently and safely.
867	 *
868	 * For EACH target: discovers every volume that must be inspected
869	 * (`discoverVolumes` — the union of configured and label-discovered
870	 * names, never label discovery alone), then re-checks EVERY one of them
871	 * with the PURE `evaluateOwnershipGate` immediately before any
872	 * destructive step — never relying on an ownership check performed
873	 * earlier in the test run, since the exact resources present at cleanup
874	 * time are what matters. Only when EVERY volume passes is
875	 * `removeContainersAndVolumes` invoked; otherwise this REFUSES the
876	 * destructive step for that target entirely (removing only
877	 * containers/network, which is always safe since they belong solely to
878	 * that target's own Compose project) and reports exactly which volumes
879	 * require manual inspection, with why. Only volumes CONFIRMED to exist
880	 * are reported as `volumesDeleted` — a confirmed-absent one had nothing
881	 * to delete.
882	 *
883	 * A failure processing ONE target (discovering its volumes — including
884	 * a fail-closed configuration-resolution failure — or either removal
885	 * call throwing) is caught and reported in that target's own outcome —
886	 * it never stops or skips the other targets, which is what makes this
887	 * safe to use for partial setup (e.g. a target whose containers never
888	 * actually started).
889	 */
890	export async function cleanupDisposableTargets(targets: DisposableCleanupTarget[]): Promise<DisposableCleanupOutcome[]> {
891	  return Promise.all(
892	    targets.map(async (target): Promise<DisposableCleanupOutcome> => {
893	      try {
894	        const records = await target.discoverVolumes();
895	        const gate = evaluateOwnershipGate(records, target.ownershipContext);
896	        if (!gate.ok) {
897	          await target.removeContainersKeepingVolumes();
898	          return {
899	            label: target.label,
900	            volumesDeleted: [],
901	            volumesRequiringManualInspection: gate.checks
902	              .filter((check) => !check.ok)
903	              .map((check) => ({ name: check.name, reason: check.reason ?? "unknown" })),
904	          };
905	        }
906	
907	        await target.removeContainersAndVolumes();
908	        const volumesDeleted = records.filter((record) => record.inspection.status === "exists").map((record) => record.name);
909	        return { label: target.label, volumesDeleted, volumesRequiringManualInspection: [] };
910	      } catch (error) {
911	        return { label: target.label, volumesDeleted: [], volumesRequiringManualInspection: [], error: String(error) };
912	      }
913	    }),
914	  );
915	}
