952	  return {
953	    label: project.projectName,
954	    discoverVolumes: () =>
955	      discoverVolumesRequiringInspection({
956	        resolveConfiguredVolumeNames: () =>
957	          resolveComposePersistence(project, env).then((resolved) => Object.values(resolved.volumeNames)),
958	        listLabeledVolumeNames: () => listVolumeNamesByComposeProject(project),
959	        inspectVolumeByName: (name) => inspectVolume(name),
960	      }),
961	    ownershipContext: { expectedProjectName: project.projectName, baselineVolumeNames, externalVolumeKeys },
