986	export interface ResolvedComposePersistence {
987	  /** The Compose project name the resolved configuration will actually use. */
988	  projectName: string;
989	  /** Volume key declared in docker-compose.yml -> the real Docker volume name Compose will create. */
990	  volumeNames: Record<string, string>;
991	  /** Volume keys declared `external: true` — a pre-existing user resource a test must never delete. */
992	  externalVolumes: string[];
993	  /** Service name -> its bind mounts (host source path, container target, read-only flag). */
994	  bindMounts: Record<string, ComposeBindMount[]>;
995	  /** Service name -> `*_DATABASE_URL` variable -> its host/port/database. Credentials are discarded, never returned. */
996	  databaseTargets: Record<string, Record<string, DatabaseTarget>>;
