999	/**
1000	 * Resolves the merged Compose configuration and extracts ONLY the
1001	 * persistence facts a test needs: volume names and their external flag,
1002	 * bind mounts, and the host/port/database of every `*_DATABASE_URL`.
1003	 *
1004	 * The underlying `docker compose config --format json` output echoes
1005	 * every interpolated development-only placeholder in plaintext
1006	 * (POSTGRES_PASSWORD, and the credentials embedded in each connection
1007	 * string) — which is exactly why `composeConfigQuiet` exists. This
1008	 * function therefore parses that document in-process and returns only
1009	 * the narrow, credential-free shape above: it never returns it, logs it,
1010	 * or includes it in an error message (a failure reports stderr only,
1011	 * never stdout). Callers must preserve that property.
1012	 *
1013	 * Requires the `docker compose` CLI but NOT a running daemon.
1014	 */
1015	export async function resolveComposePersistence(project: ComposeProject, env: ComposeEnv): Promise<ResolvedComposePersistence> {
1016	  const args = composeArgs(project, ["config", "--format", "json"]);
1017	  const result = await runToCompletion("docker", args, { cwd: project.cwd, env: withEnv(env), timeoutMs: 60000 });
1018	  if (result.exitCode !== 0) {
1019	    throw new Error(`docker compose config --format json failed (exit ${result.exitCode}):\n${result.stderr}`);
1020	  }
1021	
1022	  const parsed = JSON.parse(result.stdout) as {
1023	    name?: string;
1024	    volumes?: Record<string, { name?: string; external?: boolean } | null>;
1025	    services?: Record<
1026	      string,
1027	      {
1028	        volumes?: { type?: string; source?: string; target?: string; read_only?: boolean }[];
1029	        environment?: Record<string, string | null>;
1030	      }
1031	    >;
1032	  };
1033	
1034	  const volumeNames: Record<string, string> = {};
1035	  const externalVolumes: string[] = [];
1036	  for (const [key, definition] of Object.entries(parsed.volumes ?? {})) {
1037	    volumeNames[key] = definition?.name ?? `${parsed.name ?? project.projectName}_${key}`;
1038	    if (definition?.external === true) externalVolumes.push(key);
1039	  }
1040	
1041	  const bindMounts: Record<string, ComposeBindMount[]> = {};
1042	  const databaseTargets: Record<string, Record<string, DatabaseTarget>> = {};
1043	  for (const [serviceName, service] of Object.entries(parsed.services ?? {})) {
1044	    const binds = (service.volumes ?? [])
1045	      .filter((mount) => mount.type === "bind")
1046	      .map((mount) => ({ source: mount.source ?? "", target: mount.target ?? "", readOnly: mount.read_only === true }));
1047	    if (binds.length > 0) bindMounts[serviceName] = binds;
1048	
1049	    for (const [variable, value] of Object.entries(service.environment ?? {})) {
1050	      if (!variable.endsWith("_DATABASE_URL") || typeof value !== "string" || value.length === 0) continue;
1051	      const url = new URL(value);
1052	      databaseTargets[serviceName] ??= {};
1053	      // hostname/port/pathname only — the username and password are dropped here and never leave this function.
1054	      databaseTargets[serviceName][variable] = {
1055	        host: url.hostname,
1056	        port: url.port,
1057	        database: url.pathname.replace(/^\//, ""),
1058	      };
1059	    }
1060	  }
1061	
1062	  return { projectName: parsed.name ?? project.projectName, volumeNames, externalVolumes, bindMounts, databaseTargets };
1063	}
