1130	 * never adds an EXPOSE-only port here — only an explicit publish does),
1131	 * which is exactly the proof this sub-issue needs for `api`/`web`/`postgres`/
1132	 * `worker`/the migration services: no host port exposure, regardless of
1133	 * what the image itself exposes internally.
1134	 *
1135	 * Works on an already-exited container too (uses `getContainerId`'s own
1136	 * `-a` lookup) — required for the one-shot migration services.
1137	 */
1138	export async function getContainerHostPortBindings(project: ComposeProject, service: string): Promise<Record<string, ContainerPortBinding[] | null>> {
1139	  const containerId = await getContainerId(project, service);
1140	  if (!containerId) {
1141	    throw new Error(`No container found for service "${service}" in project ${project.projectName}`);
1142	  }
1143	  const inspect = await runToCompletion("docker", ["inspect", containerId, "--format", "{{json .HostConfig.PortBindings}}"], {
1144	    timeoutMs: 15000,
1145	  });
1146	  if (inspect.exitCode !== 0) {
1147	    throw new Error(`docker inspect "${containerId}" failed (exit ${inspect.exitCode}):\n${inspect.stderr}`);
1148	  }
