      "reachable) in this environment. Real constraint evidence was NOT produced by this run; this is a reported " +
      "blocker, not a pass.",
  );
}

async function psql(project: ComposeProject, sql: string): Promise<{ exitCode: number; stdout: string; stderr: string }> {
