    }
  } catch (error) {
    report(false, String(mode), { unexpected: error instanceof Error ? error.message : String(error) });
  } finally {
    // Always disconnect, even on a thrown/caught error above — never
    // leak the pool connection.
    await prisma.$disconnect();
    await pool.end();
  }
}

await main();

