    'INSERT INTO "projects" ("id","title","shortName","createdByUserId","provisioningState","createdAt","updatedAt") VALUES ($1,$2,$3,$4,$5,now(),now())',
    [id, "Ghost Project (no owner membership)", shortName, creatorUserId, "PROVISIONING"],
  );
}

