    const result = await composeExec(project, "postgres", ["psql", "-U", POSTGRES_USER, "-d", PROJECT_TEST_DB_NAME, "-tAc", SENTINEL_READ_SQL], { env: composeEnv });
    expect(result.exitCode, result.stderr).toBe(0);
