1	// Internal, Prisma-backed implementation of `UserRepository` (see
2	// ./types.ts for the public interface). Not exported from this package's
3	// index.ts directly — only `createControlRepositories` (control-repositories.ts)
4	// constructs one, and only the `UserRepository` INTERFACE (not this file,
5	// not the Prisma types it imports) is part of the public surface a
6	// consumer sees.
7	
8	import type { PrismaClient } from "../../generated/control-client/client.js";
9	import { isUniqueConstraintError, sanitizeUnexpectedError, uniqueConstraintTargetFields } from "./errors.js";
10	import type { CreateUserResult, CreateUserInput, UserRecord, UserRepository } from "./types.js";
11	
12	/** The minimal, safe column set every query below selects — never `passwordHash`/`passwordSalt`/`passwordParamsVersion`/`sessionTokenVersion`/pending-email-change fields (see UserRecord's own doc comment). */
13	const SAFE_USER_SELECT = {
14	  id: true,
15	  username: true,
16	  email: true,
17	  emailVerifiedAt: true,
18	  status: true,
19	  isApplicationAdministrator: true,
20	  preferredLocale: true,
21	  createdAt: true,
22	  updatedAt: true,
23	} as const;
24	
25	type SafeUserRow = {
26	  id: string;
27	  username: string;
28	  email: string;
29	  emailVerifiedAt: Date | null;
30	  status: string;
31	  isApplicationAdministrator: boolean;
32	  preferredLocale: string | null;
33	  createdAt: Date;
34	  updatedAt: Date;
35	};
36	
37	function toUserRecord(row: SafeUserRow): UserRecord {
38	  // The narrowed select above guarantees `status` only ever contains one
39	  // of these three values at the database level (the `AccountStatus`
40	  // enum) — this cast documents that guarantee rather than re-validating it.
41	  return { ...row, status: row.status as UserRecord["status"] };
42	}
43	
44	export function createUserRepository(prisma: PrismaClient): UserRepository {
45	  return {
46	    async createUser(input: CreateUserInput): Promise<CreateUserResult> {
47	      try {
48	        const row = await prisma.user.create({
49	          data: {
50	            username: input.username,
51	            email: input.email,
52	            passwordHash: input.passwordHash,
53	            passwordSalt: input.passwordSalt,
54	            passwordParamsVersion: input.passwordParamsVersion,
55	          },
56	          select: SAFE_USER_SELECT,
57	        });
58	        return { ok: true, user: toUserRecord(row) };
59	      } catch (caught) {
60	        if (isUniqueConstraintError(caught)) {
61	          const fields = uniqueConstraintTargetFields(caught);
62	          if (fields.includes("email")) return { ok: false, error: { type: "duplicate_email" } };
63	          if (fields.includes("username")) return { ok: false, error: { type: "duplicate_username" } };
64	        }
65	        throw sanitizeUnexpectedError(caught);
66	      }
67	    },
68	
69	    async findUserByEmail(email: string): Promise<UserRecord | null> {
70	      const row = await prisma.user.findUnique({ where: { email }, select: SAFE_USER_SELECT });
71	      return row ? toUserRecord(row) : null;
72	    },
73	
74	    async findUserByUsername(username: string): Promise<UserRecord | null> {
75	      const row = await prisma.user.findUnique({ where: { username }, select: SAFE_USER_SELECT });
76	      return row ? toUserRecord(row) : null;
77	    },
78	
79	    async findUserById(id: string): Promise<UserRecord | null> {
80	      const row = await prisma.user.findUnique({ where: { id }, select: SAFE_USER_SELECT });
81	      return row ? toUserRecord(row) : null;
82	    },
83	  };
84	}
