1	// Public connection-lifecycle factory for the Control DB repository
2	// surface (sub-issue 03.05). This is the ONE place `@prisma/adapter-pg`,
3	// the `pg` driver, and the generated Control client are instantiated —
4	// every repository below only ever receives the already-constructed
5	// `PrismaClient`, never a connection string or pool directly, and no
6	// Prisma type is part of this function's own public signature.
7	//
8	// Reuses the EXISTING validated Control configuration contract
9	// (`@relis/config`'s `loadDatabaseConfigForTarget`) rather than
10	// introducing a competing environment loader — the same contract
11	// src/migrate.ts already uses, so a missing/invalid `CONTROL_DATABASE_URL`
12	// fails the same way here as it does for migration (a `ConfigValidationError`
13	// with a safe, value-free diagnostic — see @relis/config's own contract).
14	
15	import { Pool } from "pg";
16	import { PrismaPg } from "@prisma/adapter-pg";
17	import { loadDatabaseConfigForTarget } from "@relis/config";
18	import { PrismaClient } from "../generated/control-client/client.js";
19	import { createMembershipRepository } from "./repositories/memberships.js";
20	import { createProjectRepository } from "./repositories/projects.js";
21	import { createUserRepository } from "./repositories/users.js";
22	import type { MembershipRepository, ProjectRepository, UserRepository } from "./repositories/types.js";
23	
24	export interface ControlRepositories {
25	  users: UserRepository;
26	  projects: ProjectRepository;
27	  memberships: MembershipRepository;
28	  /**
29	   * Closes the underlying Prisma client AND the `pg` pool it was built on
30	   * — both must be released for a clean process exit / test teardown.
31	   * Safe to call once; calling it a second time is not supported (mirrors
32	   * `PrismaClient.$disconnect()`'s own contract).
33	   */
34	  disconnect(): Promise<void>;
35	}
36	
37	/**
38	 * Constructs one set of Control repositories backed by a real PostgreSQL
39	 * connection, validated against `env` (defaults to `process.env`, exactly
40	 * like `src/migrate.ts`). Throws `@relis/config`'s `ConfigValidationError`
41	 * synchronously (before any connection attempt) if `CONTROL_DATABASE_URL`
42	 * is missing or invalid — never silently falls back to an unvalidated
43	 * value.
44	 *
45	 * Example — a consuming use case receiving repositories by injection
46	 * (never importing this factory itself, so it stays trivially testable
47	 * with a hand-written fake):
48	 * ```ts
49	 * interface Dependencies { users: UserRepository; projects: ProjectRepository }
50	 * async function registerUser(deps: Dependencies, input: CreateUserInput) {
51	 *   return deps.users.createUser(input);
52	 * }
53	 * // production wiring:
54	 * const repos = createControlRepositories();
55	 * await registerUser(repos, { username: "a", email: "a@example.test" });
56	 * // test wiring — no database, no Docker:
57	 * await registerUser({ users: fakeUserRepository, projects: fakeProjectRepository }, input);
58	 * ```
59	 */
60	export function createControlRepositories(env: NodeJS.ProcessEnv = process.env): ControlRepositories {
61	  const config = loadDatabaseConfigForTarget("control", env);
62	  const pool = new Pool({ connectionString: config.DATABASE_URL });
63	  const adapter = new PrismaPg(pool);
64	  const prisma = new PrismaClient({ adapter });
65	
66	  return {
67	    users: createUserRepository(prisma),
68	    projects: createProjectRepository(prisma),
69	    memberships: createMembershipRepository(prisma),
70	    async disconnect(): Promise<void> {
71	      await prisma.$disconnect();
72	      await pool.end();
73	    },
74	  };
75	}
76

